-- ------------------------------------------------------------------

-- Payroll Pressure: Phishing to Endpoint Compromise

-- ------------------------------------------------------------------

insert into scenarios (
  slug, title, category, difficulty, estimated_minutes, summary, briefing_md,
  learning_objectives, organization_name, root_cause, model_recommendations,
  continues_from, is_published
) values (
  'phishing-initial-access', 'Payroll Pressure: Phishing to Endpoint Compromise', 'phishing'::scenario_category,
  'beginner'::scenario_difficulty, 45,
  'An HR officer reports an urgent payroll email. Minutes later, EDR fires on Outlook spawning hidden PowerShell. Work the alert from first look to a signed-off incident report.', '## Your shift

You are the Tier 1 analyst on the morning shift at **Northwind Polytechnic**,
a 4,000-student institution with a small in-house IT team. You have an alert
queue, a log search tool, and the authority to escalate.

## What has happened so far

At 08:58 this morning, **Priya Raman** (HR officer, workstation `WKS-HR-014`)
phoned the Service Desk about an odd payroll email. She mentioned, almost in
passing, that she had already opened the attachment and that "a black window
flashed up and closed."

Five minutes later, the endpoint agent on her workstation raised a detection:
**Outlook started PowerShell with a hidden window and an encoded command.**

## What you need to do

Work this incident through all six phases. You will be asked to justify your
severity call, pull the attack apart in the logs, contain it without
destroying evidence, remove what the attacker left behind, return the user to
work safely, and write the lessons-learned section yourself.

Not every alert in your queue is part of this incident, and not every
suspicious-looking value in the logs is an indicator. Deciding what to ignore
is part of the job.

> All data in this scenario is synthetic. Addresses use RFC 5737
> documentation ranges and domains use RFC 2606 reserved TLDs; none of it
> resolves or routes anywhere.
',
  array['Separate severity from confidence when triaging a single endpoint alert.', 'Read a process tree and recognise why a signed binary can still be hostile.', 'Decode a base64 PowerShell command line and turn it into a network indicator.', 'Spot beaconing by its regularity rather than its destination.', 'Contain an endpoint without destroying the evidence you will need later.', 'Write a lessons-learned recommendation that names a specific control, not a platitude.']::text[], 'Northwind Polytechnic',
  'A spearphishing email passed the mail gateway with SPF and DMARC both failing because the gateway was configured to tag rather than quarantine on authentication failure, and attachment sandboxing was not enabled for shortcut files. The recipient opened a .lnk disguised as a PDF, which executed encoded PowerShell, downloaded a second-stage implant and established Run-key persistence with command-and-control beaconing.', array['Quarantine rather than tag inbound mail that fails DMARC, and alert the SOC on external senders using a lookalike of the institution''s own domain.', 'Enable attachment detonation for shortcut and script file types (.lnk, .js, .hta, .iso), not just Office documents and PDFs.', 'Deploy an attack-surface-reduction rule blocking Office applications from creating child processes, which would have stopped this before any network activity.', 'Enforce phishing-resistant MFA so a harvested password alone does not grant portal access.', 'Run a targeted phishing simulation for finance and HR staff, who are the recurring target of payroll-themed pretexts.']::text[],
  null, true
)
on conflict (slug) do update set
  title = excluded.title,
  category = excluded.category,
  difficulty = excluded.difficulty,
  estimated_minutes = excluded.estimated_minutes,
  summary = excluded.summary,
  briefing_md = excluded.briefing_md,
  learning_objectives = excluded.learning_objectives,
  organization_name = excluded.organization_name,
  root_cause = excluded.root_cause,
  model_recommendations = excluded.model_recommendations,
  continues_from = excluded.continues_from,
  is_published = excluded.is_published;

delete from scenario_phases where scenario_id = (select id from scenarios where slug = 'phishing-initial-access');

insert into scenario_phases (
  scenario_id, phase_key, order_index, title, instructions_md, objectives, spec, success_criteria
) values (
  (select id from scenarios where slug = 'phishing-initial-access'),
  'triage'::phase_key, 0,
  'Triage', 'Open the alert queue and read what you actually have. Four alerts are
waiting; only some belong to this incident.

Your job in this phase is **not** to solve the case. It is to decide how
urgent it is, how sure you are, and who should own it next.

Two words that get confused constantly, so be deliberate about them:

- **Severity** is about impact. How bad is this if it is real?
- **Confidence** is about evidence. How sure are you that it *is* real?

A high-severity, low-confidence alert is still worth escalating. A
low-severity, certain alert often is not. They are independent axes.
', array['Review the alert queue and open the endpoint detection.', 'Assign a severity and a confidence separately.', 'Escalate to Tier 2 rather than closing or sitting on it.']::text[],
  '{"decisions":[{"key":"alert_severity","prompt":"What severity do you assign to the EDR detection on WKS-HR-014?","help_md":"Consider impact, not certainty. One staff workstation is affected so\nfar. There is no evidence yet of a second host, a server, or student\ndata. But hidden encoded PowerShell from a mail client is a strong\nindicator of successful code execution on that endpoint.\n","type":"select","options":[{"value":"critical","label":"Critical","description":"Widespread or business-stopping impact, or confirmed impact to critical systems."},{"value":"high","label":"High","description":"Confirmed or near-certain code execution on a staff endpoint; contained blast radius so far."},{"value":"medium","label":"Medium","description":"Suspicious activity that may be benign; limited potential impact."},{"value":"low","label":"Low","description":"Policy noise or nuisance software; no meaningful impact."}],"expected":"high","points":10,"rationale_md":"**High** is the right call here.\n\nEncoded, window-hidden PowerShell launched by Outlook is close to\nconclusive evidence of execution on that endpoint, which rules out\nmedium and low. But *critical* should be reserved for incidents whose\nimpact is already widespread or is hitting systems the institution\ncannot operate without - a domain controller, the student records\nsystem, multiple departments at once.\n\nRight now this is one HR workstation. Calling it critical on the\nfirst alert spends credibility you will need later, and in a real SOC\nit wakes people up at 3am for something that could have waited until\n09:00. Severity can be raised as the blast radius grows - and in this\nincident, it will.\n","require_rationale":true},{"key":"alert_confidence","prompt":"How confident are you, right now, that this is a genuine compromise?","help_md":"You have the detection and the user''s account. You have not yet\nlooked at any network or persistence evidence.\n","type":"select","options":[{"value":"confirmed_malicious","label":"Confirmed malicious","description":"Corroborated by more than one independent source of evidence."},{"value":"likely_malicious","label":"Likely malicious","description":"Strong single-source indicator plus a plausible delivery story."},{"value":"uncertain","label":"Uncertain","description":"Could reasonably be either; needs investigation before a view."},{"value":"likely_benign","label":"Likely benign","description":"Probably legitimate administrative or business activity."}],"expected":"likely_malicious","points":10,"rationale_md":"**Likely malicious.**\n\nYou have one strong indicator (encoded PowerShell from Outlook) and a\nuser account that matches it (she opened an attachment and saw a\nwindow flash). That is more than \"uncertain.\"\n\nIt is not yet *confirmed*, because everything you have comes from a\nsingle telemetry source and a human recollection. Confirmation\narrives in the next phase when the network logs independently show\nthe download and the beacon. Being honest about that distinction is\nwhat stops a SOC from crying wolf - and from dismissing real\nincidents because someone called something \"confirmed\" once and was\nwrong.\n","require_rationale":false}],"actions":[{"key":"escalate-tier2","event_type":"ESCALATE","label":"Escalate to Tier 2","target":"Tier 2 Incident Response","description":"Hand the case to Tier 2 with your severity and confidence assessment attached.","is_correct":true,"points":10,"feedback_md":"Correct. Tier 1''s job is accurate, fast triage and a clean handoff -\nnot solving the case alone. The assessment you attached travels with\nthe ticket.\n","requires_confirmation":false},{"key":"close-false-positive","event_type":"ESCALATE","label":"Close as false positive","target":"EDR-2025-0311-4471","description":"Mark the detection as benign administrative activity and close the alert.","is_correct":false,"points":15,"feedback_md":"This is the expensive mistake this scenario exists to teach.\n\nClosing here means the beacon runs all day, the Run key survives every\nreboot, and the harvested password stays valid. Alert fatigue is real,\nand \"it''s probably an admin script\" is the most common way a genuine\nintrusion gets closed in a busy queue. Encoded, hidden PowerShell\nlaunched by a *mail client* is never routine administration.\n","requires_confirmation":true}],"hints":[{"key":"triage-hint-severity","text_md":"Ask yourself two separate questions. \"If this is real, how much\ndamage is possible right now?\" gives you severity. \"How much evidence\ndo I have that it is real?\" gives you confidence. Do not let a strong\nanswer to one drag the other along with it.\n","cost":3},{"key":"triage-hint-noise","text_md":"Two of the four alerts in the queue are ordinary background noise - a\nquarantined adware bundle and denied inbound scanning. Neither\ninvolves WKS-HR-014. Deciding they are unrelated *is* triage.\n","cost":3}]}'::jsonb, '{"required_decision_keys":["alert_severity","alert_confidence"],"required_action_keys":["escalate-tier2"],"required_ioc_values":[],"min_queries":1,"min_notes":0,"require_reflection":false,"reflection_min_words":0}'::jsonb
);

insert into scenario_phases (
  scenario_id, phase_key, order_index, title, instructions_md, objectives, spec, success_criteria
) values (
  (select id from scenarios where slug = 'phishing-initial-access'),
  'investigation'::phase_key, 1,
  'Investigation', 'Now pull the incident apart. The full log set is open to you.

Start from what you know - `WKS-HR-014`, `p.raman`, 09:03 - and pivot
outwards. Useful moves:

- `host:WKS-HR-014` to see everything that endpoint did.
- `source:dns` to look at name resolution.
- `source:proxy` for what actually left the network.

Read the EDR alert document carefully. The `-enc` argument is base64 in
UTF-16LE; the decoded command is shown for you, and it contains the single
most useful indicator in this incident.

Tag indicators as you find them. Tagging something benign costs you
points, so be able to say *why* each value is attacker infrastructure and
not just traffic you happened to notice.
', array['Recover the command-and-control domain from the encoded PowerShell.', 'Identify the beacon by its interval rather than its destination.', 'Find the persistence mechanism.', 'Establish that credentials were also harvested, not just code executed.']::text[],
  '{"decisions":[{"key":"attack_techniques","prompt":"Which MITRE ATT&CK techniques does the evidence support?","help_md":"Select only what the logs actually show. Choosing techniques that are\nnot evidenced is the analyst equivalent of guessing, and an\ninstructor reviewing your report will see both what you found and\nwhat you claimed without support.\n","type":"multi_select","options":[{"value":"T1566.001","label":"T1566.001 - Phishing: Spearphishing Attachment","description":"A targeted email carrying a malicious attachment."},{"value":"T1204.002","label":"T1204.002 - User Execution: Malicious File","description":"The compromise required the recipient to open the file."},{"value":"T1059.001","label":"T1059.001 - Command and Scripting Interpreter: PowerShell","description":"PowerShell used to execute attacker code."},{"value":"T1547.001","label":"T1547.001 - Boot or Logon Autostart Execution: Registry Run Keys","description":"Persistence via a Run key."},{"value":"T1071.001","label":"T1071.001 - Application Layer Protocol: Web Protocols","description":"Command and control over HTTP/HTTPS."},{"value":"T1190","label":"T1190 - Exploit Public-Facing Application","description":"Exploitation of an internet-facing service."},{"value":"T1110","label":"T1110 - Brute Force","description":"Repeated authentication attempts to guess credentials."},{"value":"T1021.002","label":"T1021.002 - Remote Services: SMB/Windows Admin Shares","description":"Lateral movement over SMB."},{"value":"T1486","label":"T1486 - Data Encrypted for Impact","description":"Ransomware encryption of victim files."}],"expected":["T1566.001","T1204.002","T1059.001","T1547.001","T1071.001"],"points":20,"rationale_md":"The five correct techniques trace the whole chain: the attachment\narrived (T1566.001), the user opened it (T1204.002), PowerShell ran\nthe payload (T1059.001), a Run key made it survive reboot\n(T1547.001), and it called home over HTTPS (T1071.001).\n\nThe four wrong options describe real techniques that are simply not\nin evidence here. Nothing internet-facing was exploited, there are no\nrepeated failed logons, no SMB session to a second host, and no\nencryption. Each of those belongs to a different scenario in this\nlibrary - and mapping an incident to techniques it does not show is\nhow threat intelligence gets polluted.\n","require_rationale":false},{"key":"root_cause","prompt":"What is the root cause of this incident?","help_md":"Root cause means the thing that, if it had been different, would have\nprevented the incident. Not the last thing that happened.\n","type":"select","options":[{"value":"user_opened_malicious_attachment","label":"A malicious attachment reached a user and was opened","description":"Mail controls let a hostile shortcut file through to a human, who ran it."},{"value":"unpatched_vpn","label":"An unpatched VPN appliance was exploited","description":"A known vulnerability in a perimeter device was used for access."},{"value":"sql_injection","label":"SQL injection against a web application","description":"A public-facing application was exploited through unsanitised input."},{"value":"stolen_vpn_credentials","label":"Stolen VPN credentials used for remote access","description":"Valid credentials obtained elsewhere were reused against remote access."},{"value":"insider_action","label":"Deliberate action by an insider","description":"An authorised user intentionally caused the compromise."}],"expected":"user_opened_malicious_attachment","points":15,"rationale_md":"The attachment is the root cause. Every later step - the PowerShell,\nthe download, the Run key, the beacon - depends on that file reaching\na mailbox and being executed.\n\nNote what the root cause is *not*: it is not \"the user made a\nmistake.\" Priya received mail that failed SPF and DMARC, carried a\ndouble-extension shortcut, and was not sandboxed by the gateway. The\ncontrol failed before she ever saw it. Incident reports that land on\n\"user error\" tend to produce more training and no technical change,\nand the next identical email gets through too.\n","require_rationale":true},{"key":"credential_exposure","prompt":"Were credentials exposed in this incident?","help_md":"Look at the proxy log around 08:43, before the EDR detection fired.","type":"select","options":[{"value":"yes_password_submitted","label":"Yes - a password was submitted to the lookalike portal","description":"There is evidence of a form POST to the attacker''s page."},{"value":"no_only_code_execution","label":"No - this was code execution only","description":"The attachment ran, but no credentials left the environment."},{"value":"unknown_no_evidence","label":"Unknown - the logs cannot tell us either way","description":"There is no evidence in scope to decide."}],"expected":"yes_password_submitted","points":15,"rationale_md":"Yes. `log-proxy-002` shows a **POST** to\n`northwind-sso.verify-access.example/login` at 08:43:47, followed by a\n302 redirect - the signature of a credential-harvesting page\naccepting a submission and bouncing the victim to the real site so\nnothing seems wrong.\n\nThis matters enormously for what comes later. If you treat this as\ncode execution only, you will reimage the laptop and leave a working\npassword in the attacker''s hands. Note also that the user''s own\naccount of events did not mention clicking the link. People\nunder-report, not usually dishonestly - they genuinely do not\nremember. The logs are the record; the interview is a lead.\n","require_rationale":false}],"actions":[],"hints":[{"key":"inv-hint-decode","text_md":"Open the **EDR detection** document rather than working only from the\nalert summary. It shows the full process tree and the decoded\nPowerShell command, which contains the URL the second stage came from.\n","cost":5},{"key":"inv-hint-beacon","text_md":"Run `source:dns` and look at the timestamps for\n`update-cdn.paylo4d.example`. The destination is not what gives it\naway - the *interval* is. Human browsing is never that regular.\n","cost":5},{"key":"inv-hint-persistence","text_md":"Search `source:edr`. Beyond the original detection there are two more\nendpoint events: a file being written into AppData, and a registry\nvalue being set. One of them is how the implant survives a reboot.\n","cost":5}]}'::jsonb, '{"required_decision_keys":["attack_techniques","root_cause","credential_exposure"],"required_action_keys":[],"required_ioc_values":["update-cdn.paylo4d.example","203.0.113.47","HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Run\\OneDriveSync","northwind-sso.verify-access.example"],"min_queries":3,"min_notes":1,"require_reflection":false,"reflection_min_words":0}'::jsonb
);

insert into scenario_phases (
  scenario_id, phase_key, order_index, title, instructions_md, objectives, spec, success_criteria
) values (
  (select id from scenarios where slug = 'phishing-initial-access'),
  'containment'::phase_key, 2,
  'Containment', 'Stop the bleeding. You know what is happening and where; now limit what
the attacker can still do.

Containment is a trade-off, not a checklist. Every action you take has a
cost to somebody - a user cannot work, a service goes down, or evidence
you needed is destroyed. Choose deliberately and be ready to defend each
one.

Two traps are waiting in the action panel. Both look reasonable.
', array['Isolate the affected endpoint while preserving volatile evidence.', 'Disable the account whose password was harvested.', 'Block the command-and-control infrastructure at both domain and address.', 'Avoid collateral damage to systems that are not part of the incident.']::text[],
  '{"decisions":[{"key":"containment_approach","prompt":"How should WKS-HR-014 be taken out of play?","help_md":"The implant is running in memory. Whatever you do next determines\nwhether anyone can ever analyse it.\n","type":"select","options":[{"value":"isolate_and_preserve","label":"Network-isolate the host, leave it powered on","description":"Cut network reachability from the EDR console; memory and running processes stay intact."},{"value":"power_off_immediately","label":"Power the machine off at the wall","description":"Immediate and total, and it stops everything at once."},{"value":"reimage_now","label":"Reimage the machine straight away","description":"Fastest route back to a clean, working laptop for the user."},{"value":"wait_for_approval","label":"Take no action until the IT manager approves","description":"Follow change control before touching a staff device."}],"expected":"isolate_and_preserve","points":15,"rationale_md":"**Network isolation with the host left running** is the standard\nfirst move, and it is a genuine trade-off rather than an obvious\nanswer.\n\nPulling the power destroys memory - and memory is where the\nunencrypted payload, the injected process and any in-flight\ncredentials live. Reimaging immediately destroys everything,\nincluding your ability to answer \"what did they take?\", which is the\nquestion leadership will ask first.\n\nWaiting for approval is the interesting wrong answer. Change control\nexists for good reasons, but active command-and-control on a staff\nendpoint is precisely what an emergency containment authority is for.\nIf your institution does not have one, that belongs in your\nlessons-learned section.\n","require_rationale":true}],"actions":[{"key":"isolate-host-wks-hr-014","event_type":"CONTAIN_HOST","label":"Network-isolate WKS-HR-014","target":"WKS-HR-014","description":"Cut the endpoint off from the network via the EDR console. It stays powered on and reachable by the response team.","is_correct":true,"points":15,"feedback_md":"Correct, and the order matters: isolating before disabling the account\nmeans the implant loses its channel before the attacker gets a\n\"something is wrong\" signal from a failed logon.\n","requires_confirmation":false},{"key":"disable-account-praman","event_type":"ISOLATE_ACCOUNT","label":"Disable the p.raman account and revoke sessions","target":"NORTHWIND\\p.raman","description":"Disable the account, force sign-out of all active sessions, and flag it for a password reset.","is_correct":true,"points":15,"feedback_md":"Correct. The proxy log shows the password was submitted to the\nattacker''s portal, so the credential is compromised independently of\nthe laptop. Isolating the endpoint alone would leave that password\nworking from anywhere on the internet.\n","requires_confirmation":false},{"key":"block-c2-domain","event_type":"BLOCK_INDICATOR","label":"Block update-cdn.paylo4d.example at the proxy and DNS","target":"update-cdn.paylo4d.example","description":"Add the command-and-control domain to the blocklist and sinkhole it internally.","is_correct":true,"points":10,"feedback_md":"Correct, and it protects every other endpoint too - if this email\nreached one mailbox it very likely reached others.\n","requires_confirmation":false},{"key":"block-c2-ip","event_type":"BLOCK_INDICATOR","label":"Block 203.0.113.47 at the perimeter firewall","target":"203.0.113.47","description":"Deny outbound traffic to the address the C2 domain resolves to.","is_correct":true,"points":10,"feedback_md":"Correct. Domain blocking alone is bypassed by hardcoding the address,\nwhich second-stage implants routinely do. Block both layers.\n","requires_confirmation":false},{"key":"isolate-host-wks-hr-015","event_type":"CONTAIN_HOST","label":"Network-isolate WKS-HR-015","target":"WKS-HR-015","description":"Isolate the neighbouring HR workstation as a precaution.","is_correct":false,"points":10,"feedback_md":"WKS-HR-015''s only appearance in the logs is a quarantined adware\nbundle - already handled, and unrelated. You have taken a working\nstaff member offline for nothing.\n\nPrecautionary containment is not free. Do it where there is evidence\nof spread, not where there is evidence of proximity.\n","requires_confirmation":false},{"key":"block-cdn-northwind","event_type":"BLOCK_INDICATOR","label":"Block cdn.northwind.example","target":"cdn.northwind.example","description":"The domain appears in a very large number of proxy log entries around the time of the incident.","is_correct":false,"points":15,"feedback_md":"That is the institution''s own content delivery host on an internal\naddress. You have just taken down the staff portal, the timetable\nsystem and every page that loads shared assets.\n\nIt appeared everywhere in the logs because it is used by everything.\nFrequency is not evidence of malice - in fact the most-seen values in\nany log set are almost always the most legitimate ones.\n","requires_confirmation":true}],"hints":[{"key":"contain-hint-both-layers","text_md":"Blocking the C2 domain is right but incomplete. Look at what your DNS\nlog says the domain resolves to, and ask what happens if the implant\nskips DNS entirely.\n","cost":5},{"key":"contain-hint-account","text_md":"Re-read your credential-exposure finding from the investigation\nphase. If a password left the building, containing the *laptop* does\nnot contain the *incident*.\n","cost":5}]}'::jsonb, '{"required_decision_keys":["containment_approach"],"required_action_keys":["isolate-host-wks-hr-014","disable-account-praman","block-c2-domain","block-c2-ip"],"required_ioc_values":[],"min_queries":0,"min_notes":0,"require_reflection":false,"reflection_min_words":0}'::jsonb
);

insert into scenario_phases (
  scenario_id, phase_key, order_index, title, instructions_md, objectives, spec, success_criteria
) values (
  (select id from scenarios where slug = 'phishing-initial-access'),
  'eradication'::phase_key, 3,
  'Eradication', 'Containment stopped the attacker acting. Eradication removes what they
left behind, so that restoring service does not simply restore the
compromise as well.

Be precise about what actually needs removing. Over-broad eradication
wastes days and destroys evidence; under-broad eradication means you do
this whole incident again next week.
', array['Identify every attacker artefact that must be removed.', 'Preserve forensic evidence before destroying the affected system.']::text[],
  '{"decisions":[{"key":"eradication_steps","prompt":"Which of these must be carried out to eradicate this compromise?","help_md":"Select everything required, and nothing that is not. Both misses and\nover-reach cost points, because both cost real time in a real\nincident.\n","type":"multi_select","options":[{"value":"remove_run_key","label":"Remove the OneDriveSync Run key","description":"Delete the HKCU Run value pointing at AppData."},{"value":"remove_implant_binary","label":"Delete the onedrivesync.exe implant","description":"Remove the unsigned binary from AppData\\Roaming."},{"value":"reset_praman_credentials","label":"Reset p.raman''s password and revoke tokens","description":"Issue new credentials and invalidate existing sessions and refresh tokens."},{"value":"purge_mail_from_all_mailboxes","label":"Purge the phishing email from every mailbox","description":"Search the mail estate for the same sender and attachment hash, and remove all copies."},{"value":"rebuild_endpoint","label":"Rebuild WKS-HR-014 from a known-good image","description":"Flatten and reinstall the workstation rather than cleaning it in place."},{"value":"delete_user_mailbox","label":"Delete p.raman''s mailbox","description":"Remove the mailbox entirely to be certain nothing malicious remains in it."},{"value":"rebuild_file_server","label":"Rebuild the file server","description":"Reinstall the departmental file server as a precaution."},{"value":"disable_powershell_estate_wide","label":"Disable PowerShell across the entire estate","description":"Remove PowerShell from all endpoints so this cannot happen again."}],"expected":["remove_run_key","remove_implant_binary","reset_praman_credentials","purge_mail_from_all_mailboxes","rebuild_endpoint"],"points":20,"rationale_md":"The five correct steps cover persistence, payload, credentials, the\ndelivery vector still sitting in other mailboxes, and the host\nitself.\n\nOn rebuilding: once an implant has run with user privileges and\npulled down a stage you have not analysed, cleaning in place means\ntrusting that you found everything. Rebuild from a known-good image.\n\nThe three wrong options share a shape - they are drastic actions\naimed at things that are not compromised. Deleting the mailbox\ndestroys evidence and a staff member''s work. The file server never\nappears in this incident. Disabling PowerShell estate-wide breaks\nlegitimate administration across the institution and would be\nreversed within a week; constrained language mode and\nexecution-policy controls are the proportionate version of that\ninstinct.\n","require_rationale":false},{"key":"evidence_before_rebuild","prompt":"What must happen before WKS-HR-014 is rebuilt?","type":"select","options":[{"value":"capture_forensic_image","label":"Capture a forensic disk image and memory dump","description":"Preserve the evidence while the machine still holds it."},{"value":"rebuild_immediately","label":"Rebuild immediately - the user needs the laptop","description":"Prioritise returning the staff member to work."},{"value":"copy_desktop_files","label":"Copy the user''s documents folder and rebuild","description":"Preserve the user''s work only."}],"expected":"capture_forensic_image","points":10,"rationale_md":"Image first. The moment that disk is wiped, every question that comes\nlater - what the second stage did, whether anything was staged for\nexfiltration, whether other credentials were on that machine -\nbecomes permanently unanswerable.\n\nThis is also where the chain of custody you have been building\nmatters. Your event log records who isolated the host and when; the\nforensic image records its state at that moment. Together they are\nwhat makes the incident defensible if it ever has to be explained to\na regulator, an insurer or a parent.\n","require_rationale":false}],"actions":[{"key":"request-forensic-image","event_type":"DOWNLOAD_ARTIFACT","label":"Request a forensic image of WKS-HR-014","target":"WKS-HR-014","description":"Raise a forensic acquisition request for a full disk image and memory capture before rebuild.","is_correct":true,"points":10,"feedback_md":"Correct. Requested while the host is isolated but still running,\nwhich is the only window in which memory can be captured at all.\n","requires_confirmation":false}],"hints":[{"key":"erad-hint-scope","text_md":"For each option ask: \"does this incident show that system or object\nwas touched?\" If the answer is no, removing it is not eradication -\nit is collateral damage with a security justification attached.\n","cost":5}]}'::jsonb, '{"required_decision_keys":["eradication_steps","evidence_before_rebuild"],"required_action_keys":["request-forensic-image"],"required_ioc_values":[],"min_queries":0,"min_notes":0,"require_reflection":false,"reflection_min_words":0}'::jsonb
);

insert into scenario_phases (
  scenario_id, phase_key, order_index, title, instructions_md, objectives, spec, success_criteria
) values (
  (select id from scenarios where slug = 'phishing-initial-access'),
  'recovery'::phase_key, 4,
  'Recovery', 'Get Priya back to work, and prove that it is safe to do so.

Recovery is the phase people rush, because by now the exciting part is
over and somebody senior is asking when the user gets her laptop back.
Rushing it is how incidents recur a fortnight later and everyone
concludes "the attackers came back" when in fact they never left.
', array['Restore the endpoint and account safely.', 'Define what evidence would prove the environment is clean.', 'Set a monitoring period rather than declaring victory immediately.']::text[],
  '{"decisions":[{"key":"recovery_steps","prompt":"What is required before WKS-HR-014 and the account return to normal service?","type":"multi_select","options":[{"value":"rebuild_from_known_good","label":"Rebuild from a known-good image and patch fully before reconnecting","description":"Clean build, current patch level, then network."},{"value":"reset_credentials_with_mfa","label":"Reset the password and enrol the account in phishing-resistant MFA","description":"New credential, plus a factor a harvested password cannot defeat."},{"value":"verify_no_beacon","label":"Verify no further resolution or connection to the C2 indicators","description":"Confirm from DNS, proxy and firewall telemetry that the beacon is gone."},{"value":"hunt_other_hosts","label":"Sweep the estate for the same indicators","description":"Check whether any other host contacted the C2 or received the same attachment."},{"value":"monitor_host_14_days","label":"Monitor the rebuilt host and account with raised sensitivity for 14 days","description":"Heightened alerting for a defined period before standing down."},{"value":"restore_from_yesterday_backup","label":"Restore the endpoint from yesterday evening''s backup","description":"Fast route back to the user''s exact working state."},{"value":"reconnect_and_watch","label":"Reconnect the original machine and watch what happens","description":"Return it to the network and monitor for renewed activity."}],"expected":["rebuild_from_known_good","reset_credentials_with_mfa","verify_no_beacon","hunt_other_hosts","monitor_host_14_days"],"points":20,"rationale_md":"Rebuild, new credentials with a factor that resists phishing,\npositive verification that the beacon is gone, a sweep for anyone\nelse who got the same email, and a defined monitoring window.\n\nRestoring from yesterday''s backup is the subtle trap. The attachment\narrived at 08:41 *today*, so yesterday''s image predates the\ncompromise and is technically clean - but a restore also brings back\nthe pre-incident patch level and configuration, and it silently\nskips the rebuild discipline. More importantly, students who pick it\nusually have not checked when the compromise actually began. Get into\nthe habit of asking \"is my restore point definitely before patient\nzero?\" - in the ransomware scenario in this library, it is not.\n\nReconnecting the original machine to see what happens is using the\nproduction network as a malware sandbox.\n","require_rationale":false},{"key":"recovery_signoff","prompt":"Who should sign off that the incident is closed?","type":"select","options":[{"value":"ir_lead_with_evidence","label":"The incident response lead, against documented closure criteria","description":"Closure is a decision made against stated evidence."},{"value":"tier1_analyst","label":"The Tier 1 analyst who triaged it","description":"The person closest to the alert closes it out."},{"value":"user_confirms_working","label":"The affected user, once the laptop works again","description":"Service restored is the test that matters to the business."}],"expected":"ir_lead_with_evidence","points":10,"rationale_md":"Closure is a decision with accountability attached, made against\ncriteria written down in advance - not \"the laptop boots\" and not the\njudgement of whoever happens to be on shift.\n\n\"The user says it works\" is how an incident gets closed while an\nattacker still holds a valid token somewhere else in the estate.\n","require_rationale":false}],"actions":[],"hints":[{"key":"rec-hint-backup","text_md":"Check the timestamp of the phishing email against the age of any\nbackup you are considering restoring. Ask whether the restore point\nis definitely earlier than the first attacker action - and whether\nyou actually know when that was.\n","cost":5}]}'::jsonb, '{"required_decision_keys":["recovery_steps","recovery_signoff"],"required_action_keys":[],"required_ioc_values":[],"min_queries":0,"min_notes":0,"require_reflection":false,"reflection_min_words":0}'::jsonb
);

insert into scenario_phases (
  scenario_id, phase_key, order_index, title, instructions_md, objectives, spec, success_criteria
) values (
  (select id from scenarios where slug = 'phishing-initial-access'),
  'lessons_learned'::phase_key, 5,
  'Lessons Learned', 'This is the phase most training tools skip, and the one that actually
changes anything.

An incident that ends with "we contained it and rebuilt the laptop" has
taught the institution nothing. The value of the last two hours is in
what changes because of them.

Write your post-incident review below. Aim for specifics: a
recommendation an IT manager could act on next week, with a named control
and an owner, beats "improve security awareness" every time.

Your write-up goes into the generated report verbatim, alongside the
timeline reconstructed from your own event log.
', array['Describe what happened in language a non-technical reader can follow.', 'Identify which controls worked and which did not.', 'Recommend specific, actionable changes.']::text[],
  '{"decisions":[{"key":"primary_control_gap","prompt":"Which single control failure most enabled this incident?","help_md":"Several controls underperformed. You are being asked which one, if\nfixed, would most likely have stopped the chain before it started.\n","type":"select","options":[{"value":"mail_gateway_policy","label":"The mail gateway tagged rather than quarantined a DMARC failure, and did not detonate shortcut attachments","description":"The message should never have reached a mailbox."},{"value":"user_awareness","label":"The user was not sufficiently trained to spot phishing","description":"The recipient opened an attachment they should have questioned."},{"value":"endpoint_av","label":"Antivirus failed to detect the second-stage binary","description":"The implant was written to disk without being blocked."},{"value":"firewall_rules","label":"The firewall allowed outbound HTTPS to an unknown address","description":"The beacon was permitted to leave the network."}],"expected":"mail_gateway_policy","points":15,"rationale_md":"The mail gateway. It is the earliest point in the chain where a\nsingle configuration change - quarantine on DMARC failure, detonate\nshortcut files - would have prevented everything downstream.\n\nThe other three are real weaknesses and belong in the report, but\nthey are later, weaker links. Outbound HTTPS to unknown hosts cannot\nbe blocked by default without breaking normal work. Antivirus missing\na fresh payload is expected, which is why EDR behavioural detection\nexists and, note, it *did* fire.\n\n\"User awareness\" deserves particular scrutiny. It is the most\ncommonly chosen answer in real post-incident reviews and one of the\nleast effective, because it puts the last line of defence on a person\ndoing a different job under time pressure. Training has value, but a\nreview that lands only on user error usually means the technical\ncontrols were never examined.\n","require_rationale":true}],"actions":[],"hints":[{"key":"ll-hint-specific","text_md":"Test each recommendation by asking: could someone put this in a\nchange ticket on Monday? \"Enable attachment detonation for .lnk and\n.iso files on the mail gateway\" passes. \"Be more vigilant\" does not.\n","cost":3}]}'::jsonb, '{"required_decision_keys":["primary_control_gap"],"required_action_keys":[],"required_ioc_values":[],"min_queries":0,"min_notes":0,"require_reflection":true,"reflection_min_words":120}'::jsonb
);

delete from scenario_assets where scenario_id = (select id from scenarios where slug = 'phishing-initial-access');

