((select id from scenarios where slug = 'phishing-initial-access'), 'alert-pup-hr015', 'ticket'::asset_type, '{"kind":"alert","id":"alert-pup-hr015","title":"Potentially unwanted program quarantined","severity":"low","source":"Northwind EDR","first_seen":"2025-03-11T08:47:30.000Z","description":"FreePDFToolbar.exe was quarantined on WKS-HR-015 before execution. Adware bundle, already contained by the endpoint agent.","host":"WKS-HR-015","user":"a.wong","is_decoy":true,"reveal_phase":"triage","reveal_after_seconds":0,"linked_document_ids":[],"linked_log_ids":["log-edr-n001"]}'::jsonb, true, 'triage'::phase_key),
((select id from scenarios where slug = 'phishing-initial-access'), 'alert-user-reported-phish', 'ticket'::asset_type, '{"kind":"alert","id":"alert-user-reported-phish","title":"User-reported suspicious email (payroll theme)","severity":"medium","source":"Mail Gateway / User Report","first_seen":"2025-03-11T08:58:00.000Z","description":"An HR officer reported an urgent payroll email and raised ticket SD-88214. The gateway delivered the message with SPF and DMARC both failing. The user says they opened the attachment.","host":"WKS-HR-014","user":"p.raman","is_decoy":false,"reveal_phase":"triage","reveal_after_seconds":0,"linked_document_ids":["doc-phish-email","doc-ticket"],"linked_log_ids":["log-mail-001"]}'::jsonb, false, 'triage'::phase_key),
