((select id from scenarios where slug = 'phishing-initial-access'), 'alert-edr-4471', 'ticket'::asset_type, '{"kind":"alert","id":"alert-edr-4471","title":"Office application spawned an encoded PowerShell command","severity":"high","source":"Northwind EDR","first_seen":"2025-03-11T09:03:11.000Z","description":"OUTLOOK.EXE on WKS-HR-014 started powershell.exe with -nop -w hidden -enc. The command line is base64-encoded and the window was hidden. No business process on this endpoint has done this before.","host":"WKS-HR-014","user":"p.raman","is_decoy":false,"reveal_phase":"triage","reveal_after_seconds":0,"linked_document_ids":["doc-edr-alert"],"linked_log_ids":["log-edr-001"]}'::jsonb, false, 'triage'::phase_key),
((select id from scenarios where slug = 'phishing-initial-access'), 'alert-persistence', 'ticket'::asset_type, '{"kind":"alert","id":"alert-persistence","title":"Run key created pointing at an unsigned binary in AppData","severity":"high","source":"Northwind EDR","first_seen":"2025-03-11T09:03:40.000Z","description":"A HKCU Run value named OneDriveSync now points at an unsigned executable under AppData\\Roaming. The name imitates a Microsoft component. This survives reboot and re-runs at every logon.","host":"WKS-HR-014","user":"p.raman","is_decoy":false,"reveal_phase":"triage","reveal_after_seconds":300,"linked_document_ids":["doc-edr-alert"],"linked_log_ids":["log-edr-003","log-edr-002"]}'::jsonb, false, 'triage'::phase_key),
((select id from scenarios where slug = 'phishing-initial-access'), 'alert-beacon', 'ticket'::asset_type, '{"kind":"alert","id":"alert-beacon","title":"Repeating outbound connections to a newly registered domain","severity":"critical","source":"Network Detection","first_seen":"2025-03-11T09:10:15.000Z","description":"WKS-HR-014 has resolved update-cdn.paylo4d.example every 60 seconds with near-identical request sizes. The domain was registered six days ago. This is command-and-control beaconing, not browsing.","host":"WKS-HR-014","user":"p.raman","is_decoy":false,"reveal_phase":"triage","reveal_after_seconds":150,"linked_document_ids":[],"linked_log_ids":["log-dns-beacon-001","log-dns-beacon-007","log-proxy-beacon-001"]}'::jsonb, false, 'triage'::phase_key),
((select id from scenarios where slug = 'phishing-initial-access'), 'log-auth-n001', 'auth_log'::asset_type, '{"kind":"log","id":"log-auth-n001","ts":"2025-03-11T08:04:18.000Z","source":"auth","message":"EventID=4624 Logon Type=2 (Interactive) Account=NORTHWIND\\a.wong Workstation=WKS-HR-015 Status=Success","host":"WKS-HR-015","user":"a.wong","action":"logon_success","fields":{"event_id":4624},"is_decoy":true,"reveal_phase":"investigation"}'::jsonb, true, 'investigation'::phase_key),
