((select id from scenarios where slug = 'phishing-initial-access'), 'log-fw-n001', 'firewall_log'::asset_type, '{"kind":"log","id":"log-fw-n001","ts":"2025-03-11T08:09:41.000Z","source":"firewall","message":"DENY proto=TCP src=198.51.100.77 dst=203.0.113.5 dport=22 policy=Default-Deny-Inbound","src_ip":"198.51.100.77","dst_ip":"203.0.113.5","action":"deny","fields":{"policy":"Default-Deny-Inbound","dport":22},"is_decoy":true,"reveal_phase":"investigation"}'::jsonb, true, 'investigation'::phase_key),
