((select id from scenarios where slug = 'phishing-initial-access'), 'log-auth-n002', 'auth_log'::asset_type, '{"kind":"log","id":"log-auth-n002","ts":"2025-03-11T08:21:55.000Z","source":"auth","message":"EventID=4625 Logon Type=2 (Interactive) Account=NORTHWIND\\k.lim Workstation=WKS-FIN-003 Status=Failure Reason=Bad password","host":"WKS-FIN-003","user":"k.lim","action":"logon_failure","fields":{"event_id":4625,"failure_reason":"Bad password"},"is_decoy":true,"reveal_phase":"investigation"}'::jsonb, true, 'investigation'::phase_key),
